import { createError, toError } from "../errors/index.js";
import { getGoogleGenAIEnvConfig, getOpenAIEnvConfig } from "../config/env.js";
import { createOriginBoundOutboundFetch } from "../security/http/outbound-fetch.js";
import { DEFAULT_GOOGLE_BASE_URL } from "../provider/runtime-loader/provider-endpoints.js";
import { createLocalEmbeddingModel } from "../provider/local/embedding-runtime-adapter.js";
import { tryResolve } from "../extensions/contracts.js";
import { LLMProviderRegistryName } from "../extensions/llm/index.js";
import { createVeryfrontCloudEmbeddingModel } from "./veryfront-cloud/provider.js";
const providers = new Map();
let autoInitialized = false;
/**
 * Register an embedding provider factory.
 *
 * @example
 * ```ts
 * registerEmbeddingProvider("openai", (id) => createOpenAIEmbeddingRuntime({ apiKey }, id));
 * ```
 */
export function registerEmbeddingProvider(name, factory) {
    providers.set(name, factory);
}
function autoInitializeFromEnv() {
    if (autoInitialized)
        return;
    autoInitialized = true;
    if (!providers.has("openai")) {
        providers.set("openai", (id) => {
            const config = getOpenAIEnvConfig();
            if (!config.apiKey) {
                throw toError(createError({
                    type: "config",
                    message: "OPENAI_API_KEY not set. Set the environment variable or register a custom provider with registerEmbeddingProvider().",
                }));
            }
            const registry = tryResolve(LLMProviderRegistryName);
            const provider = registry?.get("openai");
            if (provider?.createEmbedding) {
                return provider.createEmbedding(id, {
                    credential: config.apiKey,
                    baseURL: config.baseURL,
                    fetch: createOriginBoundOutboundFetch(config.baseURL ?? "https://api.openai.com/v1"),
                });
            }
            throw toError(createError({
                type: "config",
                message: "OpenAI provider not installed. Add @veryfront/ext-llm-openai to use openai/* embedding models.",
            }));
        });
    }
    if (!providers.has("google")) {
        providers.set("google", (id) => {
            const config = getGoogleGenAIEnvConfig();
            if (!config.apiKey) {
                throw toError(createError({
                    type: "config",
                    message: "GOOGLE_API_KEY (or GOOGLE_GENERATIVE_AI_API_KEY) not set. Set the environment variable or register a custom provider with registerEmbeddingProvider().",
                }));
            }
            const registry = tryResolve(LLMProviderRegistryName);
            const provider = registry?.get("google");
            if (provider?.createEmbedding) {
                return provider.createEmbedding(id, {
                    credential: config.apiKey,
                    baseURL: config.baseURL,
                    fetch: createOriginBoundOutboundFetch(config.baseURL ?? DEFAULT_GOOGLE_BASE_URL),
                });
            }
            throw toError(createError({
                type: "config",
                message: "Google provider not installed. Add @veryfront/ext-llm-google to use google/* embedding models.",
            }));
        });
    }
    if (!providers.has("local")) {
        providers.set("local", createLocalEmbeddingModel);
    }
    if (!providers.has("veryfront-cloud")) {
        providers.set("veryfront-cloud", createVeryfrontCloudEmbeddingModel);
    }
}
/**
 * Resolve a "provider/model" string to an embedding runtime instance.
 *
 * @example
 * ```ts
 * const model = resolveEmbeddingModel("openai/text-embedding-3-small");
 * ```
 */
export function resolveEmbeddingModel(modelString) {
    autoInitializeFromEnv();
    const slashIndex = modelString.indexOf("/");
    if (slashIndex === -1) {
        throw toError(createError({
            type: "config",
            message: `Invalid model string: "${modelString}". Expected "provider/model" (e.g. "openai/text-embedding-3-small").`,
        }));
    }
    const providerName = modelString.slice(0, slashIndex);
    const modelId = modelString.slice(slashIndex + 1);
    if (!providerName || !modelId) {
        throw toError(createError({
            type: "config",
            message: `Invalid model string: "${modelString}". Both provider and model name are required.`,
        }));
    }
    const factory = providers.get(providerName);
    if (!factory) {
        const available = [...providers.keys()].join(", ") || "none";
        throw toError(createError({
            type: "config",
            message: `Embedding provider "${providerName}" not registered. Available: ${available}`,
        }));
    }
    return factory(modelId);
}
/**
 * Clear all registered embedding providers (for testing).
 */
export function clearEmbeddingProviders() {
    providers.clear();
    autoInitialized = false;
}
